    # Align buckets to the first data point's timestamp
    first_ts = min(ts for ts, _ in points)
    base = first_ts - (first_ts // bucket_seconds) * bucket_seconds

    buckets: Dict[int, List[Tuple[int, float]]] = {}
    for ts, value in points:
